"""Author fixed demo-only Q32 tables offline; --check verifies exact generated bytes."""
import argparse
import hashlib
from fractions import Fraction
from pathlib import Path
import struct
from spdx_headers import with_header


def render():
    shapes = {'P': [0, 100, 0], 'Qrs': [0, -200, 1000, -100, 0],
              'T': [0, 300, 0], 'Resp': [0, 1000, 0]}
    lines = ['// Generated by tools/generate_demo_morphology.py; do not edit.',
             '// Project-authored synthetic fixtures, not validated physiology.',
             'namespace Monitor.Desktop;', '', 'internal static class PhysiologyDemoTables', '{']
    for name, knots in shapes.items():
        steps = 64 // (len(knots) - 1)
        values = []
        for first, last in zip(knots, knots[1:]):
            for index in range(steps):
                t = Fraction(index, steps)
                value = (first + (last - first) * (3 * t * t - 2 * t * t * t)) * (1 << 32)
                values.append(round(value))
        digest = hashlib.sha256(b''.join(struct.pack('<q', value) for value in values)).hexdigest()
        lines += [f'    // Q32 little-endian table SHA-256: {digest}',
                  f'    internal static IReadOnlyList<long> {name} {{ get; }} = Array.AsReadOnly(new long[]', '    {']
        for offset in range(0, len(values), 4):
            lines.append('        ' + ', '.join(str(value) for value in values[offset:offset + 4]) + ',')
        lines += ['    });']
    lines += ['}', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    target = Path(__file__).resolve().parent.parent / 'src/Monitor.Desktop/PhysiologyDemoTables.cs'
    expected = with_header(target.name, render().encode()).decode()
    if args.check:
        if target.read_text() != expected:
            raise SystemExit('Demo morphology differs from reproducible table output')
        print('ok: four 64-point demo Q32 morphology tables match offline authoring')
    else:
        target.write_text(expected)


if __name__ == '__main__':
    main()
